// Setor Clínica › Acompanhamento e Continuidade
import { useState, useRef, useEffect } from "react";
import { ResponsiveContainer, LineChart, CartesianGrid, XAxis, YAxis, Tooltip, Line } from "recharts";
import { dPlus, fmtDate } from "../../../data/clinica";
import { tipStyle } from "../../../data/comum";
import { api } from "../../../services/api";
import { type Patient } from "../../../types/clinica";
import { PREVENTION_PROGRAMS, PROTOCOLS } from "./dados";
import { type ActiveItem, type AdhGoal, type AdhLog, type ChronicProgram, type PostItem, type PrevInvite, type ProgStatus, type Quest, type Retorno, type SharedPlan, type VaccineRec } from "./tipos";

export function ContinuityModule({ patients, onNotice, onOpenPatient }: { patients: Patient[]; onNotice: (m: string) => void; onOpenPatient: (id: string) => void }) {
  const [tab, setTab] = useState("Programas");
  const [programs, setPrograms] = useState<ChronicProgram[]>([
    { id: "prog-hiper", name: "Hipertensão", goal: "PA < 130/80 mmHg", adherence: 78, members: [{ patientId: "p1", status: "Controlado" }, { patientId: "p4", status: "Em acompanhamento" }, { patientId: "p9", status: "Controlado" }] },
    { id: "prog-diab", name: "Diabetes", goal: "HbA1c < 7% · glicemia em meta", adherence: 71, members: [{ patientId: "p1", status: "Em acompanhamento" }, { patientId: "p5", status: "Em acompanhamento" }] },
    { id: "prog-obes", name: "Obesidade", goal: "Reduzir 5% do peso em 90 dias", adherence: 64, members: [{ patientId: "p2", status: "Em acompanhamento" }, { patientId: "p4", status: "Descompensado" }] },
    { id: "prog-asma", name: "Asma", goal: "Sem crises · uso correto do inalador", adherence: 82, members: [{ patientId: "p3", status: "Controlado" }, { patientId: "p6", status: "Em acompanhamento" }] },
  ]);
  const [openProg, setOpenProg] = useState<string | null>("prog-hiper");
  const [newProg, setNewProg] = useState({ name: "", goal: "" });
  const [enroll, setEnroll] = useState<Record<string, { patientId: string; status: ProgStatus }>>({});
  const [protocolId, setProtocolId] = useState("hipertensao");
  const [protocolPatient, setProtocolPatient] = useState("p1");
  const [checks, setChecks] = useState<Record<string, boolean>>({});
  const [returns, setReturns] = useState<Retorno[]>([
    { id: "ret-1", patientId: "p1", date: dPlus(0), reason: "Retorno — controle de PA e diabetes", professional: "Dra. Ana Paula — Clínica Geral" },
    { id: "ret-2", patientId: "p4", date: dPlus(3), reason: "Retorno — cardiologia / ajuste de medicação", professional: "Dr. Roberto — Cardiologia" },
    { id: "ret-3", patientId: "p7", date: dPlus(-2), reason: "Retorno pós-alta — insuficiência cardíaca", professional: "Dra. Ana Paula — Clínica Geral" },
    { id: "ret-4", patientId: "p5", date: dPlus(6), reason: "Retorno — pré-natal", professional: "Dra. Juliana — Obstetrícia" },
  ]);
  const [retFilter, setRetFilter] = useState("Todos");
  const [retForm, setRetForm] = useState({ patientId: "p1", date: dPlus(7), reason: "", professional: "Dra. Ana Paula — Clínica Geral" });
  const [waReturn, setWaReturn] = useState<Retorno | null>(null);
  const [activeItems, setActiveItems] = useState<ActiveItem[]>([
    { id: "bus-1", patientId: "p2", type: "Sem retorno há +90 dias", detail: "Último retorno há mais de 90 dias. Confirmar se precisa reagendar." },
    { id: "bus-2", patientId: "p7", type: "Exame em atraso", detail: "Exame de função renal em atraso. Verificar coleta e resultado." },
    { id: "bus-3", patientId: "p3", type: "Vacina em atraso", detail: "Vacina de reforço em atraso no calendário vacinal." },
    { id: "bus-4", patientId: "p9", type: "Sem retorno há +90 dias", detail: "Sem retorno registrado há mais de 90 dias. Confirmar acompanhamento." },
  ]);
  const [waActive, setWaActive] = useState<ActiveItem | null>(null);
  const [adhPatient, setAdhPatient] = useState("p1");
  const [adhGoals, setAdhGoals] = useState<AdhGoal[]>([
    { id: "ag-1", patientId: "p1", label: "Pressão arterial", target: "< 130/80 mmHg", progress: 62 },
    { id: "ag-2", patientId: "p1", label: "Glicemia", target: "70–130 mg/dL em jejum", progress: 55 },
    { id: "ag-3", patientId: "p1", label: "Peso", target: "Reduzir 4 kg", progress: 40 },
    { id: "ag-4", patientId: "p4", label: "Pressão arterial", target: "< 130/80 mmHg", progress: 58 },
  ]);
  const [adhLogs, setAdhLogs] = useState<AdhLog[]>([
    { id: "al-1", patientId: "p1", date: dPlus(-3), med: "Boa", diet: "Regular", activity: "Boa", note: "Tomou medicação todos os dias." },
    { id: "al-2", patientId: "p1", date: dPlus(-1), med: "Boa", diet: "Boa", activity: "Regular", note: "Caminhada de 30 minutos." },
  ]);
  const [adhForm, setAdhForm] = useState({ med: "Boa", diet: "Boa", activity: "Boa", note: "" });
  const [newGoal, setNewGoal] = useState({ label: "Pressão arterial", target: "", progress: 0 });
  const [vacPatient, setVacPatient] = useState("p1");
  const [vaccines, setVaccines] = useState<VaccineRec[]>([
    { id: "vac-1", patientId: "p1", name: "Influenza", status: "Aplicada", date: "2026-04-10", lot: "INF-2210" },
    { id: "vac-2", patientId: "p1", name: "COVID", status: "Aplicada", date: "2026-03-02", lot: "COV-1187" },
    { id: "vac-3", patientId: "p1", name: "Pneumo", status: "Pendente", date: dPlus(14), lot: "—" },
    { id: "vac-4", patientId: "p3", name: "Influenza", status: "Atrasada", date: dPlus(-12), lot: "—" },
    { id: "vac-5", patientId: "p3", name: "COVID", status: "Aplicada", date: "2026-04-20", lot: "COV-1201" },
    { id: "vac-6", patientId: "p7", name: "Tétano", status: "Atrasada", date: dPlus(-20), lot: "—" },
    { id: "vac-7", patientId: "p5", name: "Hepatite B", status: "Pendente", date: dPlus(10), lot: "—" },
  ]);
  const [vacForm, setVacForm] = useState({ name: "Influenza", status: "Aplicada" as VaccineRec["status"], date: dPlus(0), lot: "" });
  const [prevProgram, setPrevProgram] = useState(PREVENTION_PROGRAMS[0]);
  const [invites, setInvites] = useState<PrevInvite[]>([
    { id: "pv-1", program: "Check-up anual", patientId: "p2", status: "Agendado" },
    { id: "pv-2", program: "Check-up anual", patientId: "p8", status: "Convidado" },
    { id: "pv-3", program: "Campanha Outubro Rosa", patientId: "p9", status: "Convidado" },
    { id: "pv-4", program: "Novembro Azul", patientId: "p4", status: "Realizado" },
    { id: "pv-5", program: "Rastreamento de câncer", patientId: "p1", status: "Agendado" },
  ]);
  const [invitePatient, setInvitePatient] = useState("p1");
  const [postItems, setPostItems] = useState<PostItem[]>([
    { id: "post-1", patientId: "p7", dischargeDate: dPlus(-5), procedure: "Internação — descompensação cardíaca", contactDate: dPlus(2), status: "Acompanhando", contacts: [{ date: dPlus(-2), note: "Ligação: paciente estável, sem edema novo." }] },
    { id: "post-2", patientId: "p8", dischargeDate: dPlus(-10), procedure: "Imobilização — fratura", contactDate: dPlus(4), status: "Acompanhando", contacts: [{ date: dPlus(-3), note: "Orientado repouso e retorno em 2 semanas." }] },
  ]);
  const [postNote, setPostNote] = useState<Record<string, string>>({});
  const [questPatient, setQuestPatient] = useState("p1");
  const [quests, setQuests] = useState<Quest[]>([
    { id: "q-1", patientId: "p1", date: dPlus(-7), pain: 3, dyspnea: 2, sleep: 6, disposition: 6, note: "Sem piora." },
    { id: "q-2", patientId: "p1", date: dPlus(-1), pain: 4, dyspnea: 3, sleep: 5, disposition: 5, note: "Sono um pouco pior." },
  ]);
  const [questForm, setQuestForm] = useState({ pain: 3, dyspnea: 2, sleep: 6, disposition: 6, note: "" });
  const [sharedPatient, setSharedPatient] = useState("p1");
  const [shared, setShared] = useState<Record<string, SharedPlan>>({
    p1: { patientId: "p1", text: "Acompanhamento de pressão e diabetes com retornos regulares, medicação nos horários certos e exames de controle.", goalsText: "Manter a pressão abaixo de 130/80 e a glicemia na meta. Caminhar 30 minutos na maioria dos dias.", orientations: "Tomar a medicação todos os dias, reduzir o sal, beber água e procurar a Clínica se sentir falta de ar, dor no peito ou tontura." },
  });
  const [sharedForm, setSharedForm] = useState({ text: "", goalsText: "", orientations: "" });
  const [sharedView, setSharedView] = useState<"profissional" | "paciente">("paciente");
  const [waShared, setWaShared] = useState(false);
  const recIds = useRef<Record<string, string>>({});
  const inputCls = "w-full rounded-xl border border-[var(--line)] bg-[var(--surface)] px-3 py-2.5 text-sm outline-none";
  const labelCls = "block text-sm font-bold";
  const pname = (id: string) => patients.find(p => p.id === id)?.name || id;
  const pphone = (id: string) => patients.find(p => p.id === id)?.phone || "—";
  async function persist(kind: string, entity: any) {
    const key = `${kind}:${entity.id || entity.patientId}`;
    try {
      const value = { kind, ...entity };
      if (recIds.current[key]) await api("records.replace", { collection: "gottcured_continuidade", id: recIds.current[key], value });
      else { const created: any = await api("records.create", { collection: "gottcured_continuidade", value, idempotency_key: `gottcured-cont-${kind}-${entity.id || entity.patientId}` }); if (created?.id) recIds.current[key] = created.id; }
    } catch { /* mantém na sessão; sincronização será tentada novamente */ }
  }
  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const data: any = await api("records.list", { collection: "gottcured_continuidade" });
        if (!alive || !data?.records?.length) return;
        const merge = <T extends { id?: string; patientId?: string }>(prev: T[], loaded: any[], key: "id" | "patientId") => { const m = new Map(prev.map(x => [x[key] as string, x])); for (const x of loaded) m.set(x[key], { ...(m.get(x[key]) || {}), ...x } as T); return Array.from(m.values()); };
        const loadedByKind: Record<string, any[]> = {};
        for (const r of data.records) { const v = r.value || {}; if (v.kind) { (loadedByKind[v.kind] = loadedByKind[v.kind] || []).push(v); recIds.current[`${v.kind}:${v.id || v.patientId}`] = r.id; } }
        if (loadedByKind.program) setPrograms(p => merge(p, loadedByKind.program, "id"));
        if (loadedByKind.return) setReturns(p => merge(p, loadedByKind.return, "id"));
        if (loadedByKind.active) setActiveItems(p => merge(p, loadedByKind.active, "id"));
        if (loadedByKind.adh_goal) setAdhGoals(p => merge(p, loadedByKind.adh_goal, "id"));
        if (loadedByKind.adh_log) setAdhLogs(p => merge(p, loadedByKind.adh_log, "id"));
        if (loadedByKind.vaccine) setVaccines(p => merge(p, loadedByKind.vaccine, "id"));
        if (loadedByKind.invite) setInvites(p => merge(p, loadedByKind.invite, "id"));
        if (loadedByKind.post) setPostItems(p => merge(p, loadedByKind.post, "id"));
        if (loadedByKind.questionnaire) setQuests(p => merge(p, loadedByKind.questionnaire, "id"));
        if (loadedByKind.protocol_check) { const m: Record<string, boolean> = {}; for (const x of loadedByKind.protocol_check) m[x.id] = !!x.checked; setChecks(prev => ({ ...prev, ...m })); }
        if (loadedByKind.shared) { const m: Record<string, SharedPlan> = {}; for (const x of loadedByKind.shared) m[x.patientId] = x; setShared(prev => ({ ...prev, ...m })); }
      } catch { }
    })();
    return () => { alive = false; };
  }, []);
  function createProgram() { if (!newProg.name.trim()) { onNotice("Informe o nome do programa."); return; } const p: ChronicProgram = { id: `prog-${Date.now()}`, name: newProg.name.trim(), goal: newProg.goal.trim() || "Meta a definir com a equipe", adherence: 0, members: [] }; setPrograms(prev => [...prev, p]); persist("program", p); setNewProg({ name: "", goal: "" }); setOpenProg(p.id); onNotice(`Programa “${p.name}” criado.`); }
  function enrollPatient(prog: ChronicProgram) { const sel = enroll[prog.id] || { patientId: patients[0]?.id || "", status: "Em acompanhamento" as ProgStatus }; if (!sel.patientId) return; if (prog.members.some(m => m.patientId === sel.patientId)) { onNotice(`${pname(sel.patientId)} já está inscrito neste programa.`); return; } const next = { ...prog, members: [...prog.members, { patientId: sel.patientId, status: sel.status }] }; setPrograms(prev => prev.map(x => x.id === prog.id ? next : x)); persist("program", next); onNotice(`${pname(sel.patientId)} inscrito no programa ${prog.name} — ${sel.status}.`); }
  function setMemberStatus(prog: ChronicProgram, patientId: string, status: ProgStatus) { const next = { ...prog, members: prog.members.map(m => m.patientId === patientId ? { ...m, status } : m) }; setPrograms(prev => prev.map(x => x.id === prog.id ? next : x)); persist("program", next); }
  function toggleCheck(protocol: string, patientId: string, step: number, item: number) { const id = `${protocol}-${patientId}-${step}-${item}`; setChecks(prev => { const next = { ...prev, [id]: !prev[id] }; persist("protocol_check", { id, checked: next[id] }); return next; }); }
  function addReturn() { if (!retForm.reason.trim()) { onNotice("Informe o motivo do retorno."); return; } const r: Retorno = { id: `ret-${Date.now()}`, patientId: retForm.patientId, date: retForm.date, reason: retForm.reason.trim(), professional: retForm.professional }; setReturns(prev => [...prev, r]); persist("return", r); setRetForm({ ...retForm, reason: "" }); onNotice(`Retorno agendado para ${pname(r.patientId)} em ${fmtDate(r.date)}.`); }
  function confirmReminder() { if (!waReturn) return; const next = { ...waReturn, reminderSent: true, reminderAt: new Date().toLocaleString("pt-BR") }; setReturns(prev => prev.map(x => x.id === next.id ? next : x)); persist("return", next); setWaReturn(null); onNotice(`Lembrete enviado por WhatsApp para ${pname(next.patientId)} (simulado).`); }
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const filteredReturns = returns.filter(r => { const d = new Date(r.date + "T00:00:00"); if (retFilter === "Hoje") return d.getTime() === today.getTime(); if (retFilter === "Esta semana") return d.getTime() >= today.getTime() && d.getTime() <= today.getTime() + 6 * 86400000; if (retFilter === "Atrasados") return d.getTime() < today.getTime(); return true; }).sort((a, b) => a.date.localeCompare(b.date));
  function doActive(action: string, item: ActiveItem) {
    if (action === "Mensagem") { setWaActive(item); return; }
    if (action === "Agendar") { const r: Retorno = { id: `ret-${Date.now()}`, patientId: item.patientId, date: dPlus(7), reason: `Retorno — busca ativa (${item.type})`, professional: "Dra. Ana Paula — Clínica Geral" }; setReturns(prev => [...prev, r]); persist("return", r); }
    const next = { ...item, done: true, doneAt: new Date().toLocaleString("pt-BR"), channel: action }; setActiveItems(prev => prev.map(x => x.id === item.id ? next : x)); persist("active", next); onNotice(`Busca ativa realizada para ${pname(item.patientId)} — ${action}.`);
  }
  function confirmActiveMsg() { if (!waActive) return; const next = { ...waActive, done: true, doneAt: new Date().toLocaleString("pt-BR"), channel: "Mensagem" }; setActiveItems(prev => prev.map(x => x.id === next.id ? next : x)); persist("active", next); setWaActive(null); onNotice(`Mensagem enviada por WhatsApp para ${pname(next.patientId)} (simulado). Busca ativa realizada.`); }
  const scoreOf = (v: string) => v === "Boa" ? 100 : v === "Regular" ? 60 : 25;
  const myLogs = adhLogs.filter(l => l.patientId === adhPatient);
  const adherencePct = myLogs.length ? Math.round(myLogs.reduce((s, l) => s + (scoreOf(l.med) + scoreOf(l.diet) + scoreOf(l.activity)) / 3, 0) / myLogs.length) : 0;
  function addAdhLog() { const l: AdhLog = { id: `al-${Date.now()}`, patientId: adhPatient, date: new Date().toISOString().slice(0, 10), med: adhForm.med, diet: adhForm.diet, activity: adhForm.activity, note: adhForm.note.trim() }; setAdhLogs(prev => [l, ...prev]); persist("adh_log", l); setAdhForm({ ...adhForm, note: "" }); onNotice("Registro de adesão salvo."); }
  function addGoal() { if (!newGoal.target.trim()) { onNotice("Informe a meta terapêutica."); return; } const g: AdhGoal = { id: `ag-${Date.now()}`, patientId: adhPatient, label: newGoal.label, target: newGoal.target.trim(), progress: Number(newGoal.progress) || 0 }; setAdhGoals(prev => [...prev, g]); persist("adh_goal", g); setNewGoal({ ...newGoal, target: "", progress: 0 }); onNotice("Meta terapêutica criada."); }
  function setGoalProgress(g: AdhGoal, progress: number) { const next = { ...g, progress }; setAdhGoals(prev => prev.map(x => x.id === g.id ? next : x)); persist("adh_goal", next); }
  function registerVaccine() { const v: VaccineRec = { id: `vac-${Date.now()}`, patientId: vacPatient, name: vacForm.name, status: vacForm.status, date: vacForm.date, lot: vacForm.lot.trim() || "—" }; setVaccines(prev => [...prev, v]); persist("vaccine", v); onNotice(`${v.name} registrada para ${pname(v.patientId)} — ${v.status}.`); }
  function markVaccineApplied(v: VaccineRec) { const next = { ...v, status: "Aplicada" as const, date: new Date().toISOString().slice(0, 10), lot: v.lot === "—" ? "Lote a confirmar" : v.lot }; setVaccines(prev => prev.map(x => x.id === v.id ? next : x)); persist("vaccine", next); onNotice(`${v.name} marcada como aplicada para ${pname(v.patientId)}.`); }
  function invite() { const inv: PrevInvite = { id: `pv-${Date.now()}`, program: prevProgram, patientId: invitePatient, status: "Convidado" }; setInvites(prev => [...prev, inv]); persist("invite", inv); onNotice(`${pname(invitePatient)} convidado para ${prevProgram}.`); }
  function setInviteStatus(inv: PrevInvite, status: PrevInvite["status"]) { const next = { ...inv, status }; setInvites(prev => prev.map(x => x.id === inv.id ? next : x)); persist("invite", next); }
  function addPostContact(item: PostItem) { const note = (postNote[item.id] || "").trim(); if (!note) { onNotice("Escreva o contato pós-alta antes de registrar."); return; } const next = { ...item, contactDate: new Date().toISOString().slice(0, 10), contacts: [...item.contacts, { date: new Date().toLocaleDateString("pt-BR"), note }] }; setPostItems(prev => prev.map(x => x.id === item.id ? next : x)); persist("post", next); setPostNote(prev => ({ ...prev, [item.id]: "" })); onNotice("Contato pós-alta registrado."); }
  function setPostStatus(item: PostItem, status: PostItem["status"]) { const next = { ...item, status }; setPostItems(prev => prev.map(x => x.id === item.id ? next : x)); persist("post", next); }
  function saveQuest() { const q: Quest = { id: `q-${Date.now()}`, patientId: questPatient, date: new Date().toISOString().slice(0, 10), pain: questForm.pain, dyspnea: questForm.dyspnea, sleep: questForm.sleep, disposition: questForm.disposition, note: questForm.note.trim() }; setQuests(prev => [...prev, q]); persist("questionnaire", q); onNotice("Questionário salvo."); }
  const myQuests = [...quests.filter(q => q.patientId === questPatient)].sort((a, b) => a.date.localeCompare(b.date));
  const questAlert = myQuests.length >= 2 && (myQuests[myQuests.length - 1].pain - myQuests[myQuests.length - 2].pain >= 3 || myQuests[myQuests.length - 1].pain >= 8) ? "Alerta: dor piorou ou está alta (≥ 8). Reavaliar o paciente." : myQuests.length && myQuests[myQuests.length - 1].pain >= 7 ? "Alerta: dor alta (≥ 7). Reavaliar o paciente." : "";
  const currentShared = shared[sharedPatient];
  function editShared() { setSharedForm({ text: currentShared?.text || "", goalsText: currentShared?.goalsText || "", orientations: currentShared?.orientations || "" }); }
  function saveShared() { if (!sharedForm.text.trim()) { onNotice("Escreva o plano de cuidado antes de salvar."); return; } const plan: SharedPlan = { patientId: sharedPatient, text: sharedForm.text.trim(), goalsText: sharedForm.goalsText.trim(), orientations: sharedForm.orientations.trim(), sharedAt: currentShared?.sharedAt }; setShared(prev => ({ ...prev, [sharedPatient]: plan })); persist("shared", { id: sharedPatient, ...plan }); onNotice("Plano de cuidado salvo."); }
  function confirmShare() { const plan: SharedPlan = { ...(currentShared || { patientId: sharedPatient, text: "", goalsText: "", orientations: "" }), sharedAt: new Date().toLocaleString("pt-BR") }; setShared(prev => ({ ...prev, [sharedPatient]: plan })); persist("shared", { id: sharedPatient, ...plan }); setWaShared(false); onNotice(`Plano compartilhado com ${pname(sharedPatient)} por WhatsApp (simulado).`); }
  const tabs = ["Programas", "Protocolos", "Retornos", "Busca ativa", "Metas e adesão", "Vacinação", "Prevenção", "Pós-alta", "Questionários", "Plano compartilhado"];
  const vacNames = ["Influenza", "COVID", "Hepatite B", "Tétano", "Pneumo"];
  const myVaccines = vaccines.filter(v => v.patientId === vacPatient);
  const nextDoses = vaccines.filter(v => v.status !== "Aplicada").sort((a, b) => a.date.localeCompare(b.date));
  const protocol = PROTOCOLS.find(p => p.id === protocolId)!;
  const protocolTotal = protocol.steps.reduce((s, st) => s + st.items.length, 0);
  const protocolDone = protocol.steps.reduce((s, st, si) => s + st.items.filter((_, ii) => checks[`${protocolId}-${protocolPatient}-${si}-${ii}`]).length, 0);
  return <div>
    <div className="flex gap-2 overflow-x-auto pb-1 no-scrollbar">{tabs.map(t => <button key={t} onClick={() => setTab(t)} className={`pill shrink-0 px-3.5 py-2 text-[13px] font-semibold ${tab === t ? "chip-active" : ""}`}>{t}</button>)}</div>
    {tab === "Programas" && <div className="mt-4">
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{programs.map(p => <article key={p.id} className="card p-4"><p className="text-[12px] font-bold uppercase tracking-wide text-[var(--muted)]">Programa de crônicos</p><h3 className="mt-1 text-[18px] font-extrabold">{p.name}</h3><p className="mt-1 text-sm text-[var(--muted)]">Meta: {p.goal}</p><p className="mt-2 text-sm"><strong>{p.members.length}</strong> pacientes inscritos · Adesão <strong>{p.adherence}%</strong></p><div className="mt-2 h-2.5 overflow-hidden rounded-full bg-[var(--surface-2)]"><div className="h-full rounded-full bg-[var(--primary)]" style={{ width: `${p.adherence}%` }} /></div><button onClick={() => setOpenProg(openProg === p.id ? null : p.id)} className="mt-3 rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">{openProg === p.id ? "Fechar lista" : "Ver pacientes"}</button></article>)}
      <div className="card p-4"><p className="text-[12px] font-bold uppercase tracking-wide text-[var(--muted)]">Novo programa</p><h3 className="mt-1 text-[18px] font-extrabold">Criar programa</h3><input value={newProg.name} onChange={e => setNewProg({ ...newProg, name: e.target.value })} placeholder="Ex.: Doença renal crônica" className={`${inputCls} mt-3`} aria-label="Nome do novo programa" /><input value={newProg.goal} onChange={e => setNewProg({ ...newProg, goal: e.target.value })} placeholder="Meta do programa" className={`${inputCls} mt-2`} aria-label="Meta do novo programa" /><button onClick={createProgram} className="mt-3 rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">Criar programa</button></div></div>
      {openProg && (() => { const prog = programs.find(p => p.id === openProg)!; if (!prog) return null; return <div className="mt-4 soft p-4"><div className="flex flex-wrap items-center justify-between gap-2"><h3 className="font-extrabold">Pacientes — {prog.name} ({prog.members.length})</h3><span className="text-sm text-[var(--muted)]">Meta: {prog.goal} · Adesão {prog.adherence}%</span></div><div className="mt-3 grid gap-2 sm:grid-cols-[1fr_180px_auto]"><select value={(enroll[prog.id]?.patientId) || patients[0]?.id || ""} onChange={e => setEnroll(prev => ({ ...prev, [prog.id]: { ...(prev[prog.id] || { patientId: "", status: "Em acompanhamento" as ProgStatus }), patientId: e.target.value } }))} className={inputCls} aria-label="Paciente para inscrever">{patients.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select><select value={enroll[prog.id]?.status || "Em acompanhamento"} onChange={e => setEnroll(prev => ({ ...prev, [prog.id]: { ...(prev[prog.id] || { patientId: patients[0]?.id || "", status: "Em acompanhamento" as ProgStatus }), status: e.target.value as ProgStatus } }))} className={inputCls} aria-label="Status no programa"><option>Controlado</option><option>Em acompanhamento</option><option>Descompensado</option></select><button onClick={() => enrollPatient(prog)} className="rounded-full bg-[var(--primary)] px-4 py-2.5 text-sm font-bold text-white">Inscrever paciente</button></div><div className="mt-3 space-y-2">{prog.members.map(m => <div key={m.patientId} className="soft flex flex-wrap items-center justify-between gap-2 p-3"><div><p className="font-bold text-sm">{pname(m.patientId)}</p><p className="text-xs text-[var(--muted)]">{pphone(m.patientId)} · <button onClick={() => onOpenPatient(m.patientId)} className="font-bold text-[var(--primary)]">Abrir prontuário →</button></p></div><select value={m.status} onChange={e => setMemberStatus(prog, m.patientId, e.target.value as ProgStatus)} className="rounded-full border border-[var(--line)] bg-[var(--surface)] px-3 py-2 text-sm" aria-label={`Status de ${pname(m.patientId)}`}><option>Controlado</option><option>Em acompanhamento</option><option>Descompensado</option></select></div>)}{!prog.members.length && <p className="text-sm text-[var(--muted)]">Nenhum paciente inscrito. Inscreva um paciente acima.</p>}</div></div>; })()}
    </div>}
    {tab === "Protocolos" && <div className="mt-4">
      <div className="grid gap-2 sm:grid-cols-2"><label className={labelCls}>Condição / protocolo<select value={protocolId} onChange={e => setProtocolId(e.target.value)} className={`${inputCls} mt-1`}>{PROTOCOLS.map(p => <option key={p.id} value={p.id}>{p.condition}</option>)}</select></label><label className={labelCls}>Paciente<select value={protocolPatient} onChange={e => setProtocolPatient(e.target.value)} className={`${inputCls} mt-1`}>{patients.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></label></div>
      <p className="mt-3 text-sm text-[var(--muted)]">Protocolo de {protocol.condition} para {pname(protocolPatient)} · {protocolDone}/{protocolTotal} itens concluídos ({protocolTotal ? Math.round(protocolDone / protocolTotal * 100) : 0}%).</p>
      <div className="mt-2 h-2.5 overflow-hidden rounded-full bg-[var(--surface-2)]"><div className="h-full rounded-full bg-[var(--primary)]" style={{ width: `${protocolTotal ? protocolDone / protocolTotal * 100 : 0}%` }} /></div>
      <div className="mt-4 grid gap-3 md:grid-cols-2">{protocol.steps.map((st, si) => <div key={st.title} className="soft p-4"><h3 className="font-extrabold">{st.title}</h3><div className="mt-2 space-y-2">{st.items.map((it, ii) => { const key = `${protocolId}-${protocolPatient}-${si}-${ii}`; return <label key={it} className="flex items-start gap-2 text-sm"><input type="checkbox" checked={!!checks[key]} onChange={() => toggleCheck(protocolId, protocolPatient, si, ii)} className="mt-0.5 h-4 w-4 accent-[#0F5F5C]" /><span className={checks[key] ? "line-through text-[var(--muted)]" : ""}>{it}</span></label>; })}</div></div>)}</div>
      <div className="mt-4 flex flex-wrap gap-2">{PROTOCOLS.map(p => <button key={p.id} onClick={() => setProtocolId(p.id)} className={`pill px-3 py-2 text-[13px] font-bold ${protocolId === p.id ? "chip-active" : ""}`}>{p.condition}</button>)}</div>
    </div>}
    {tab === "Retornos" && <div className="mt-4">
      <div className="flex flex-wrap gap-2">{["Todos", "Hoje", "Esta semana", "Atrasados"].map(f => <button key={f} onClick={() => setRetFilter(f)} className={`pill px-3.5 py-2 text-[13px] font-semibold ${retFilter === f ? "chip-active" : ""}`}>{f}</button>)}</div>
      <div className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><label className={labelCls}>Paciente<select value={retForm.patientId} onChange={e => setRetForm({ ...retForm, patientId: e.target.value })} className={`${inputCls} mt-1`}>{patients.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label className={labelCls}>Data<input type="date" value={retForm.date} onChange={e => setRetForm({ ...retForm, date: e.target.value })} className={`${inputCls} mt-1`} /></label><label className={labelCls}>Motivo<input value={retForm.reason} onChange={e => setRetForm({ ...retForm, reason: e.target.value })} placeholder="Ex.: Retorno — controle de PA" className={`${inputCls} mt-1`} /></label><label className={labelCls}>Profissional<input value={retForm.professional} onChange={e => setRetForm({ ...retForm, professional: e.target.value })} className={`${inputCls} mt-1`} /></label></div>
      <button onClick={addReturn} className="mt-3 rounded-full bg-[var(--primary)] px-5 py-2.5 text-sm font-bold text-white">Agendar retorno</button>
      <div className="mt-4 space-y-2">{filteredReturns.map(r => <article key={r.id} className="soft flex flex-wrap items-center justify-between gap-3 p-4"><div><p className="font-bold">{pname(r.patientId)} · {fmtDate(r.date)}</p><p className="mt-1 text-sm text-[var(--muted)]">{r.reason} · {r.professional} · {pphone(r.patientId)}</p>{r.reminderSent && <p className="mt-1 text-[13px] font-bold text-[#1E5B2A]">✓ Lembrete enviado · {r.reminderAt}</p>}</div><div className="flex flex-wrap gap-2"><button onClick={() => setWaReturn(r)} className="rounded-full bg-[#177E4B] px-4 py-2 text-[13px] font-bold text-white">Enviar lembrete</button><button onClick={() => onOpenPatient(r.patientId)} className="pill px-4 py-2 text-[13px] font-bold">Ver paciente</button></div></article>)}{!filteredReturns.length && <p className="text-sm text-[var(--muted)]">Nenhum retorno com esse filtro.</p>}</div>
    </div>}
    {tab === "Busca ativa" && <div className="mt-4"><p className="text-sm text-[var(--muted)]">{activeItems.filter(a => !a.done).length} pendente(s) · {activeItems.filter(a => a.done).length} busca(s) realizada(s)</p><div className="mt-3 space-y-3">{activeItems.map(a => <article key={a.id} className={`soft p-4 ${a.done ? "opacity-80" : ""}`}><div className="flex flex-wrap justify-between gap-2"><p className="font-bold">{a.type} — {pname(a.patientId)}</p><span className={`rounded-full px-2.5 py-1 text-[11px] font-bold ${a.done ? "bg-[var(--primary-soft)] text-[var(--primary)]" : "bg-[#FFF0C5] text-[#7A5600]"}`}>{a.done ? `Busca ativa realizada · ${a.doneAt}` : "Pendente"}</span></div><p className="mt-1 text-sm text-[var(--muted)]">{a.detail} · {pphone(a.patientId)}</p>{a.done && <p className="mt-1 text-[13px] font-bold">Canal: {a.channel}</p>}{!a.done && <div className="mt-3 flex flex-wrap gap-2"><button onClick={() => doActive("Ligação", a)} className="rounded-full bg-[var(--primary)] px-4 py-2 text-[13px] font-bold text-white">Ligar</button><button onClick={() => doActive("Mensagem", a)} className="rounded-full bg-[#177E4B] px-4 py-2 text-[13px] font-bold text-white">Enviar mensagem</button><button onClick={() => doActive("Agendar", a)} className="pill px-4 py-2 text-[13px] font-bold">Agendar</button></div>}</article>)}</div></div>}
    {tab === "Metas e adesão" && <div className="mt-4">
      <label className={labelCls}>Paciente<select value={adhPatient} onChange={e => setAdhPatient(e.target.value)} className={`${inputCls} mt-1 max-w-[420px]`}>{patients.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></label>
      <div className="mt-4 flex flex-wrap items-center gap-3"><p className="font-extrabold">Adesão ao tratamento: {adherencePct}%</p><div className="h-2.5 w-48 overflow-hidden rounded-full bg-[var(--surface-2)]"><div className="h-full rounded-full bg-[var(--primary)]" style={{ width: `${adherencePct}%` }} /></div><span className="text-sm text-[var(--muted)]">{myLogs.length} registro(s)</span></div>
      {adherencePct > 0 && adherencePct < 60 && <p className="mt-2 rounded-xl bg-[#F8DEDC] px-3 py-2 text-sm font-bold text-[#8B2626]">⚠ Alerta: adesão baixa ({adherencePct}%). Reavaliar medicação, dieta e atividade com o paciente.</p>}
      <h3 className="mt-5 font-extrabold">Metas terapêuticas</h3><div className="mt-2 space-y-2">{adhGoals.filter(g => g.patientId === adhPatient).map(g => <div key={g.id} className="soft p-3"><div className="flex flex-wrap justify-between gap-2"><p className="font-bold text-sm">{g.label} · {g.target}</p><span className="text-sm font-bold">{g.progress}%</span></div><div className="mt-2 h-2.5 overflow-hidden rounded-full bg-[var(--surface-2)]"><div className="h-full rounded-full bg-[var(--primary)]" style={{ width: `${g.progress}%` }} /></div><label className="mt-2 block text-sm">Atualizar progresso <input type="range" min={0} max={100} value={g.progress} onChange={e => setGoalProgress(g, Number(e.target.value))} className="ml-1 w-40 align-middle accent-[#0F5F5C]" /></label></div>)}{!adhGoals.some(g => g.patientId === adhPatient) && <p className="text-sm text-[var(--muted)]">Nenhuma meta para este paciente. Crie uma abaixo.</p>}</div>
      <div className="mt-3 grid gap-2 sm:grid-cols-[180px_1fr_120px_auto]"><select value={newGoal.label} onChange={e => setNewGoal({ ...newGoal, label: e.target.value })} className={inputCls} aria-label="Tipo de meta"><option>Pressão arterial</option><option>Glicemia</option><option>Peso</option><option>Colesterol</option></select><input value={newGoal.target} onChange={e => setNewGoal({ ...newGoal, target: e.target.value })} placeholder="Ex.: PA < 130/80 mmHg" className={inputCls} aria-label="Meta terapêutica" /><input type="number" min={0} max={100} value={newGoal.progress} onChange={e => setNewGoal({ ...newGoal, progress: Number(e.target.value) })} className={inputCls} aria-label="Progresso inicial" /><button onClick={addGoal} className="rounded-full bg-[var(--primary)] px-4 py-2.5 text-sm font-bold text-white">Criar meta</button></div>
      <h3 className="mt-5 font-extrabold">Registrar adesão</h3><div className="mt-2 grid gap-2 sm:grid-cols-3">{([["med", "Tomou medicação?"], ["diet", "Seguiu dieta?"], ["activity", "Praticou atividade?"]] as const).map(([k, label]) => <label key={k} className={labelCls}>{label}<select value={(adhForm as any)[k]} onChange={e => setAdhForm({ ...adhForm, [k]: e.target.value })} className={`${inputCls} mt-1`}><option>Boa</option><option>Regular</option><option>Ruim</option></select></label>)}</div><input value={adhForm.note} onChange={e => setAdhForm({ ...adhForm, note: e.target.value })} placeholder="Observação (opcional)" className={`${inputCls} mt-2`} aria-label="Observação da adesão" /><button onClick={addAdhLog} className="mt-3 rounded-full bg-[var(--primary)] px-5 py-2.5 text-sm font-bold text-white">Salvar adesão</button>
      <div className="mt-4 space-y-2">{myLogs.map(l => <div key={l.id} className="soft p-3 text-sm"><p className="font-bold">{fmtDate(l.date)} · Medicação: {l.med} · Dieta: {l.diet} · Atividade: {l.activity}</p>{l.note && <p className="mt-1 text-[var(--muted)]">{l.note}</p>}</div>)}</div>
    </div>}
    {tab === "Vacinação" && <div className="mt-4">
      <label className={labelCls}>Paciente<select value={vacPatient} onChange={e => setVacPatient(e.target.value)} className={`${inputCls} mt-1 max-w-[420px]`}>{patients.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></label>
      <h3 className="mt-4 font-extrabold">Carteira vacinal — {pname(vacPatient)}</h3><div className="mt-2 space-y-2">{myVaccines.map(v => <div key={v.id} className="soft flex flex-wrap items-center justify-between gap-2 p-3"><div><p className="font-bold text-sm">{v.name} · {v.status}</p><p className="text-xs text-[var(--muted)]">Data: {fmtDate(v.date)} · Lote: {v.lot}</p></div>{v.status !== "Aplicada" && <button onClick={() => markVaccineApplied(v)} className="rounded-full bg-[var(--primary)] px-3 py-1.5 text-xs font-bold text-white">Registrar aplicação</button>}</div>)}{!myVaccines.length && <p className="text-sm text-[var(--muted)]">Nenhuma vacina registrada. Registre abaixo.</p>}</div>
      <h3 className="mt-5 font-extrabold">Registrar aplicação / agendar dose</h3><div className="mt-2 grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><select value={vacForm.name} onChange={e => setVacForm({ ...vacForm, name: e.target.value })} className={inputCls} aria-label="Vacina">{vacNames.map(v => <option key={v}>{v}</option>)}</select><select value={vacForm.status} onChange={e => setVacForm({ ...vacForm, status: e.target.value as VaccineRec["status"] })} className={inputCls} aria-label="Status da vacina"><option>Aplicada</option><option>Pendente</option><option>Atrasada</option></select><input type="date" value={vacForm.date} onChange={e => setVacForm({ ...vacForm, date: e.target.value })} className={inputCls} aria-label="Data da vacina" /><input value={vacForm.lot} onChange={e => setVacForm({ ...vacForm, lot: e.target.value })} placeholder="Lote (ex.: INF-2210)" className={inputCls} aria-label="Lote" /></div><button onClick={registerVaccine} className="mt-3 rounded-full bg-[var(--primary)] px-5 py-2.5 text-sm font-bold text-white">Registrar aplicação</button>
      <h3 className="mt-5 font-extrabold">Calendário vacinal — próximas doses</h3><div className="mt-2 space-y-2">{nextDoses.map(v => <div key={v.id} className="soft flex flex-wrap justify-between gap-2 p-3 text-sm"><span><strong>{v.name}</strong> — {pname(v.patientId)} · {fmtDate(v.date)}</span><span className={`rounded-full px-2.5 py-1 text-[11px] font-bold ${v.status === "Atrasada" ? "bg-[#F8DEDC] text-[#8B2626]" : "bg-[#FFF0C5] text-[#7A5600]"}`}>{v.status}</span></div>)}{!nextDoses.length && <p className="text-sm text-[var(--muted)]">Nenhuma dose pendente.</p>}</div>
    </div>}
    {tab === "Prevenção" && <div className="mt-4">
      <div className="grid gap-2 sm:grid-cols-[1fr_1fr_auto]"><select value={prevProgram} onChange={e => setPrevProgram(e.target.value)} className={inputCls} aria-label="Programa de prevenção">{PREVENTION_PROGRAMS.map(p => <option key={p}>{p}</option>)}</select><select value={invitePatient} onChange={e => setInvitePatient(e.target.value)} className={inputCls} aria-label="Paciente elegível">{patients.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select><button onClick={invite} className="rounded-full bg-[var(--primary)] px-4 py-2.5 text-sm font-bold text-white">Convidar paciente</button></div>
      <p className="mt-3 text-sm text-[var(--muted)]">Pacientes elegíveis: todos os pacientes da Clínica podem ser convidados. {invites.filter(i => i.program === prevProgram).length} convidado(s) em {prevProgram}.</p>
      <div className="mt-3 space-y-2">{invites.filter(i => i.program === prevProgram).map(inv => <div key={inv.id} className="soft flex flex-wrap items-center justify-between gap-2 p-3"><div><p className="font-bold text-sm">{pname(inv.patientId)} · {inv.program}</p><p className="text-xs text-[var(--muted)]">{pphone(inv.patientId)}</p></div><div className="flex flex-wrap gap-1.5"><span className={`rounded-full px-2.5 py-1 text-[11px] font-bold ${inv.status === "Realizado" ? "bg-[var(--primary-soft)] text-[var(--primary)]" : inv.status === "Agendado" ? "bg-[#FFF0C5] text-[#7A5600]" : "bg-[var(--surface-2)] text-[var(--muted)]"}`}>{inv.status}</span>{inv.status === "Convidado" && <button onClick={() => setInviteStatus(inv, "Agendado")} className="pill px-3 py-1 text-xs font-bold">Agendar</button>}{inv.status === "Agendado" && <button onClick={() => setInviteStatus(inv, "Realizado")} className="rounded-full bg-[var(--primary)] px-3 py-1 text-xs font-bold text-white">Marcar como Realizado</button>}</div></div>)}{!invites.some(i => i.program === prevProgram) && <p className="text-sm text-[var(--muted)]">Nenhum paciente convidado para este programa.</p>}</div>
      <div className="mt-4 flex flex-wrap gap-2">{PREVENTION_PROGRAMS.map(p => <button key={p} onClick={() => setPrevProgram(p)} className={`pill px-3 py-2 text-[13px] font-bold ${prevProgram === p ? "chip-active" : ""}`}>{p}</button>)}</div>
    </div>}
    {tab === "Pós-alta" && <div className="mt-4"><div className="space-y-3">{postItems.map(item => <article key={item.id} className="soft p-4"><div className="flex flex-wrap justify-between gap-2"><div><p className="font-bold">{pname(item.patientId)} · Alta em {fmtDate(item.dischargeDate)}</p><p className="mt-1 text-sm text-[var(--muted)]">{item.procedure} · Contato de acompanhamento: {fmtDate(item.contactDate)} · {pphone(item.patientId)}</p></div><select value={item.status} onChange={e => setPostStatus(item, e.target.value as PostItem["status"])} className="rounded-full border border-[var(--line)] bg-[var(--surface)] px-3 py-2 text-sm" aria-label="Status pós-alta"><option>Acompanhando</option><option>Concluído</option><option>Intercorrência</option></select></div><div className="mt-3 space-y-1">{item.contacts.map((c, i) => <p key={i} className="text-sm"><strong>{c.date}:</strong> {c.note}</p>)}</div><div className="mt-3 flex flex-wrap gap-2"><input value={postNote[item.id] || ""} onChange={e => setPostNote(prev => ({ ...prev, [item.id]: e.target.value }))} placeholder="Registrar contato pós-alta…" className={`${inputCls} flex-1 min-w-[200px]`} aria-label="Contato pós-alta" /><button onClick={() => addPostContact(item)} className="rounded-full bg-[var(--primary)] px-4 py-2.5 text-sm font-bold text-white">Registrar contato</button><button onClick={() => onOpenPatient(item.patientId)} className="pill px-4 py-2.5 text-sm font-bold">Ver paciente</button></div></article>)}</div></div>}
    {tab === "Questionários" && <div className="mt-4">
      <label className={labelCls}>Paciente<select value={questPatient} onChange={e => setQuestPatient(e.target.value)} className={`${inputCls} mt-1 max-w-[420px]`}>{patients.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></label>
      {questAlert && <p className="mt-3 rounded-xl bg-[#F8DEDC] px-3 py-2 text-sm font-bold text-[#8B2626]">{questAlert}</p>}
      <div className="mt-4 grid gap-3 sm:grid-cols-2">{([["pain", "Dor (0–10)"], ["dyspnea", "Dispneia / falta de ar (0–10)"], ["sleep", "Qualidade do sono (0–10)"], ["disposition", "Disposição (0–10)"]] as const).map(([k, label]) => <label key={k} className={labelCls}>{label}: <strong>{(questForm as any)[k]}</strong><input type="range" min={0} max={10} value={(questForm as any)[k]} onChange={e => setQuestForm({ ...questForm, [k]: Number(e.target.value) })} className="mt-1 w-full accent-[#0F5F5C]" /></label>)}</div>
      <input value={questForm.note} onChange={e => setQuestForm({ ...questForm, note: e.target.value })} placeholder="Observação (opcional)" className={`${inputCls} mt-2`} aria-label="Observação do questionário" /><button onClick={saveQuest} className="mt-3 rounded-full bg-[var(--primary)] px-5 py-2.5 text-sm font-bold text-white">Salvar questionário</button>
      <h3 className="mt-5 font-extrabold">Evolução — {pname(questPatient)}</h3>
      {myQuests.length ? <div className="mt-2 h-[240px]"><ResponsiveContainer><LineChart data={myQuests.map(q => ({ data: fmtDate(q.date), dor: q.pain, dispneia: q.dyspnea, sono: q.sleep, disposicao: q.disposition }))}><CartesianGrid stroke="var(--line)" vertical={false} /><XAxis dataKey="data" tick={{ fill: "var(--muted)", fontSize: 11 }} /><YAxis domain={[0, 10]} tick={{ fill: "var(--muted)", fontSize: 11 }} /><Tooltip contentStyle={tipStyle} /><Line type="monotone" dataKey="dor" stroke="#C83E3E" strokeWidth={2.5} name="Dor" /><Line type="monotone" dataKey="dispneia" stroke="#E4A11B" strokeWidth={2.5} name="Dispneia" /><Line type="monotone" dataKey="sono" stroke="#2C7FA6" strokeWidth={2.5} name="Sono" /><Line type="monotone" dataKey="disposicao" stroke="#177E4B" strokeWidth={2.5} name="Disposição" /></LineChart></ResponsiveContainer></div> : <p className="mt-2 text-sm text-[var(--muted)]">Nenhum questionário. Responda e salve acima.</p>}
      <div className="mt-3 space-y-2">{myQuests.map(q => <div key={q.id} className="soft p-3 text-sm"><p className="font-bold">{fmtDate(q.date)} · Dor {q.pain} · Dispneia {q.dyspnea} · Sono {q.sleep} · Disposição {q.disposition}</p>{q.note && <p className="mt-1 text-[var(--muted)]">{q.note}</p>}</div>)}</div>
    </div>}
    {tab === "Plano compartilhado" && <div className="mt-4">
      <label className={labelCls}>Paciente<select value={sharedPatient} onChange={e => { setSharedPatient(e.target.value); setSharedForm({ text: "", goalsText: "", orientations: "" }); }} className={`${inputCls} mt-1 max-w-[420px]`}>{patients.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select></label>
      <div className="mt-3 flex gap-2"><button onClick={() => setSharedView("paciente")} className={`pill px-3.5 py-2 text-[13px] font-semibold ${sharedView === "paciente" ? "chip-active" : ""}`}>Visão do paciente</button><button onClick={() => setSharedView("profissional")} className={`pill px-3.5 py-2 text-[13px] font-semibold ${sharedView === "profissional" ? "chip-active" : ""}`}>Visão profissional</button><button onClick={editShared} className="pill px-3.5 py-2 text-[13px] font-semibold">Editar plano</button></div>
      {sharedView === "paciente" && <div className="mt-4 soft p-4"><p className="text-[12px] font-bold uppercase tracking-wide text-[var(--muted)]">Visão do paciente · linguagem simples</p><h3 className="mt-2 text-[18px] font-extrabold">Olá, {pname(sharedPatient).split(" ")[0]}! Este é o seu plano de cuidado.</h3><p className="mt-2 text-[15px] leading-7">{currentShared?.text || "Ainda não há um plano de cuidado para este paciente. Peça à equipe para criar o seu plano."}</p>{currentShared?.goalsText && <><p className="mt-3 font-bold">Suas metas</p><p className="mt-1 text-[15px] leading-7">{currentShared.goalsText}</p></>}{currentShared?.orientations && <><p className="mt-3 font-bold">O que fazer no dia a dia</p><p className="mt-1 text-[15px] leading-7">{currentShared.orientations}</p></>}{currentShared?.sharedAt && <p className="mt-3 text-sm font-bold text-[#1E5B2A]">✓ Compartilhado com o paciente · {currentShared.sharedAt}</p>}</div>}
      {sharedView === "profissional" && <div className="mt-4 space-y-3"><label className={labelCls}>Plano de cuidado<textarea value={sharedForm.text} onChange={e => setSharedForm({ ...sharedForm, text: e.target.value })} rows={3} className={`${inputCls} mt-1`} placeholder="Plano de cuidado…" /></label><label className={labelCls}>Metas<textarea value={sharedForm.goalsText} onChange={e => setSharedForm({ ...sharedForm, goalsText: e.target.value })} rows={2} className={`${inputCls} mt-1`} placeholder="Metas do plano…" /></label><label className={labelCls}>Orientações<textarea value={sharedForm.orientations} onChange={e => setSharedForm({ ...sharedForm, orientations: e.target.value })} rows={3} className={`${inputCls} mt-1`} placeholder="Orientações para o paciente…" /></label><div className="flex flex-wrap gap-2"><button onClick={saveShared} className="rounded-full bg-[var(--primary)] px-5 py-2.5 text-sm font-bold text-white">Salvar plano</button><button onClick={() => { if (!currentShared?.text) { onNotice("Salve o plano antes de compartilhar."); return; } setWaShared(true); }} className="rounded-full bg-[#177E4B] px-5 py-2.5 text-sm font-bold text-white">Compartilhar com paciente (WhatsApp)</button></div></div>}
    </div>}
    {waReturn && <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/40 p-4" onClick={() => setWaReturn(null)}><div className="w-full max-w-[440px] overflow-hidden rounded-3xl bg-[#E7F0E9] shadow-2xl" onClick={e => e.stopPropagation()}><div className="bg-[var(--primary)] px-4 py-3 text-white"><p className="font-extrabold">WhatsApp — {pname(waReturn.patientId)}</p><p className="text-xs opacity-80">{pphone(waReturn.patientId)} · janela simulada</p></div><div className="p-4"><div className="rounded-2xl bg-white p-3 text-sm leading-6">Olá, {pname(waReturn.patientId).split(" ")[0]}! Lembrete da Clínica: seu retorno é em {fmtDate(waReturn.date)} — {waReturn.reason}, com {waReturn.professional}. Confirme sua presença, por favor.</div></div><div className="flex gap-2 bg-white px-4 py-3"><button onClick={confirmReminder} className="flex-1 rounded-full bg-[#177E4B] px-4 py-2.5 text-sm font-bold text-white">Enviar</button><button onClick={() => setWaReturn(null)} className="pill px-4 py-2.5 text-sm font-bold">Cancelar</button></div></div></div>}
    {waActive && <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/40 p-4" onClick={() => setWaActive(null)}><div className="w-full max-w-[440px] overflow-hidden rounded-3xl bg-[#E7F0E9] shadow-2xl" onClick={e => e.stopPropagation()}><div className="bg-[var(--primary)] px-4 py-3 text-white"><p className="font-extrabold">WhatsApp — {pname(waActive.patientId)}</p><p className="text-xs opacity-80">{pphone(waActive.patientId)} · janela simulada</p></div><div className="p-4"><div className="rounded-2xl bg-white p-3 text-sm leading-6">Olá, {pname(waActive.patientId).split(" ")[0]}! Aqui é a Clínica GottCured. Notamos: {waActive.detail} Podemos ajudar a reagendar ou atualizar seus exames?</div></div><div className="flex gap-2 bg-white px-4 py-3"><button onClick={confirmActiveMsg} className="flex-1 rounded-full bg-[#177E4B] px-4 py-2.5 text-sm font-bold text-white">Enviar</button><button onClick={() => setWaActive(null)} className="pill px-4 py-2.5 text-sm font-bold">Cancelar</button></div></div></div>}
    {waShared && <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/40 p-4" onClick={() => setWaShared(false)}><div className="w-full max-w-[440px] overflow-hidden rounded-3xl bg-[#E7F0E9] shadow-2xl" onClick={e => e.stopPropagation()}><div className="bg-[var(--primary)] px-4 py-3 text-white"><p className="font-extrabold">WhatsApp — {pname(sharedPatient)}</p><p className="text-xs opacity-80">{pphone(sharedPatient)} · janela simulada</p></div><div className="p-4"><div className="rounded-2xl bg-white p-3 text-sm leading-6 whitespace-pre-wrap">Olá, {pname(sharedPatient).split(" ")[0]}! Este é o seu plano de cuidado:{"\n\n"}{currentShared?.text}{currentShared?.goalsText ? `\n\nSuas metas: ${currentShared.goalsText}` : ""}{currentShared?.orientations ? `\n\nO que fazer no dia a dia: ${currentShared.orientations}` : ""}</div></div><div className="flex gap-2 bg-white px-4 py-3"><button onClick={confirmShare} className="flex-1 rounded-full bg-[#177E4B] px-4 py-2.5 text-sm font-bold text-white">Enviar</button><button onClick={() => setWaShared(false)} className="pill px-4 py-2.5 text-sm font-bold">Cancelar</button></div></div></div>}
  </div>;
}
